-- Replaces the 48 combined Lazy Lifter day-plans (Easy Cook / No-Cook
-- Bulking / No-Cook Cutting, each holding Meal A/B/C... inside one row's
-- meal_breakdown) with standalone Food Prep entries -- one row per meal,
-- each a normal single-item menu entry with its own per-100g macros, the
-- same shape as every other prep_meals row. The Easy Cook / No-Cook tabs
-- go away; a new "Resto/Instant food" tab replaces them for restaurant
-- and ready-to-eat items. Each split meal is auto-sorted using: brand/
-- restaurant/canned/instant ingredient keywords -> Resto-Instant; else a
-- meal marked "(Snack)" in the source PDF -> Snack; else the day's first
-- meal -> Breakfast; else -> Full Meal. Move any individual item
-- afterward with the normal admin editor's Category dropdown.
--
-- Order matters: the 48 day-plan rows are deleted while the OLD category
-- constraint (which still allows 'easy_cook'/'no_cook') is in effect,
-- THEN the constraint is updated to the new 4-category set, THEN the 224
-- split rows are inserted (they need 'resto_instant' to already be
-- allowed). Safe to re-run in full.

delete from prep_meals where category in ('easy_cook', 'no_cook');

alter table prep_meals drop constraint if exists prep_meals_category_check;
alter table prep_meals add constraint prep_meals_category_check check (category in ('breakfast', 'full_meal', 'snack', 'resto_instant'));

